package generator

import (
	"bytes"
	"fmt"

	"gopkg.in/yaml.v2"
)

// GeneratedMarker is the first line of every generated file. The publisher
// uses it to tell generated files (overwrite) from hand-written ones (back up
// first).
const GeneratedMarker = "# Code generated by cfg-generator. DO NOT EDIT."

// droppedTopLevelKeys are keys yaml.v2 emits for fields that are not part of
// the config format. NF Config structs embed sync.RWMutex, which yaml.v2
// serializes as `rwmutex: {}`.
var droppedTopLevelKeys = map[string]bool{"rwmutex": true}

// Marshal serializes an NF config into the bytes of its output file.
func Marshal(cfg any) (out []byte, err error) {
	// yaml.v2 panics on unsupported types (e.g. channels) instead of
	// returning an error.
	defer func() {
		if r := recover(); r != nil {
			out, err = nil, fmt.Errorf("marshal: %v", r)
		}
	}()

	raw, err := yaml.Marshal(cfg)
	if err != nil {
		return nil, err
	}

	// Re-decode into an ordered map to drop unwanted top-level keys. This
	// round trip is safe for leading-zero strings: the first Marshal already
	// quoted them ("010203"), so they decode back as strings.
	var doc yaml.MapSlice
	if err = yaml.Unmarshal(raw, &doc); err != nil {
		return nil, fmt.Errorf("re-decode generated yaml: %w", err)
	}
	kept := doc[:0]
	for _, item := range doc {
		if k, ok := item.Key.(string); ok && droppedTopLevelKeys[k] {
			continue
		}
		kept = append(kept, item)
	}
	body, err := yaml.Marshal(kept)
	if err != nil {
		return nil, err
	}

	var buf bytes.Buffer
	buf.WriteString(GeneratedMarker)
	buf.WriteByte('\n')
	buf.Write(body)
	return buf.Bytes(), nil
}
